import Foundation

/// A plain rendering of a PowerPoint deck for when Quick Look can't make one (it gives up on some decks, such as
/// many generated by scripts): every slide at its size, with its background, its text boxes (size, weight,
/// color, alignment), filled shapes, pictures and table text where they sit. Not pixel-perfect (no theme colors,
/// effects or charts), but every slide is there and readable.
enum PptxRenderer {
    struct Run { var text: String; var size: Double?; var bold = false; var italic = false; var color: String? }
    struct Paragraph { var runs: [Run] = []; var align = "left" }
    struct Shape {
        var x = 0.0, y = 0.0, w = 0.0, h = 0.0
        var fill: String?
        var image: String?
        var paragraphs: [Paragraph] = []
    }
    struct Slide { var background: String?; var shapes: [Shape] = [] }

    /// Unzips `deck` into `folder` and writes `slides.html` there; nil when it isn't a readable deck.
    static func render(_ deck: URL, into folder: URL) -> URL? {
        let unzipped = folder.appendingPathComponent("deck")
        let unzip = Process()
        unzip.executableURL = URL(fileURLWithPath: "/usr/bin/unzip")
        unzip.arguments = ["-qo", deck.path, "-d", unzipped.path]
        unzip.standardOutput = FileHandle.nullDevice
        unzip.standardError = FileHandle.nullDevice
        guard (try? unzip.run()) != nil else { return nil }
        unzip.waitUntilExit()
        let ppt = unzipped.appendingPathComponent("ppt")
        guard let presentation = try? Data(contentsOf: ppt.appendingPathComponent("presentation.xml")) else { return nil }
        let (size, order) = PresentationReader.read(presentation)
        let rels = Relationships.read(ppt.appendingPathComponent("_rels/presentation.xml.rels"))
        let width = size.cx > 0 ? size.cx : 12_192_000, height = size.cy > 0 ? size.cy : 6_858_000
        var slides: [(Slide, URL)] = []
        for id in order {
            guard let target = rels[id] else { continue }
            let file = ppt.appendingPathComponent(target).standardizedFileURL
            guard let data = try? Data(contentsOf: file) else { continue }
            let slideRels = Relationships.read(file.deletingLastPathComponent().appendingPathComponent("_rels/\(file.lastPathComponent).rels"))
            var slide = SlideReader.read(data)
            for i in slide.shapes.indices {
                if let rid = slide.shapes[i].image, let target = slideRels[rid] {
                    let media = file.deletingLastPathComponent().appendingPathComponent(target).standardizedFileURL
                    slide.shapes[i].image = media.path.hasPrefix(folder.path + "/") ? String(media.path.dropFirst(folder.path.count + 1)) : nil
                } else {
                    slide.shapes[i].image = nil
                }
            }
            slides.append((slide, file))
        }
        guard !slides.isEmpty else { return nil }
        let page = folder.appendingPathComponent("slides.html")
        let html = self.html(slides.map(\.0), width: width, height: height)
        guard (try? html.write(to: page, atomically: true, encoding: .utf8)) != nil else { return nil }
        return page
    }

    /// The slides as one page, each 960 px wide, stacked.
    static func html(_ slides: [Slide], width: Double, height: Double) -> String {
        let scale = 960 / width
        let slideHeight = Int((height * scale).rounded())
        var out = """
        <!doctype html><html><head><meta charset="utf-8"><style>
        body { margin: 0; padding: 16px 0; background: #2b2d33; font-family: -apple-system, "Helvetica Neue", sans-serif; }
        .slide { position: relative; width: 960px; height: \(slideHeight)px; margin: 0 auto 16px; overflow: hidden;
                 background: #fff; box-shadow: 0 2px 10px rgba(0,0,0,.4); }
        .slide .n { position: absolute; right: 8px; bottom: 6px; font-size: 11px; color: rgba(127,127,127,.8); }
        .s { position: absolute; overflow: hidden; }
        .s p { margin: 0; line-height: 1.2; white-space: pre-wrap; }
        .s img { width: 100%; height: 100%; object-fit: contain; }
        </style></head><body>
        """
        for (index, slide) in slides.enumerated() {
            let dark = slide.background.map { luminance($0) < 0.45 } ?? false
            let textColor = dark ? "#ffffff" : "#111111"
            out += "<div class=\"slide\" style=\"background:\(slide.background.map { "#" + $0 } ?? "#fff")\">"
            for shape in slide.shapes {
                let box = "left:\(px(shape.x * scale))px;top:\(px(shape.y * scale))px;width:\(px(shape.w * scale))px;height:\(px(shape.h * scale))px"
                if let image = shape.image {
                    out += "<div class=\"s\" style=\"\(box)\"><img src=\"\(escape(image))\"></div>"
                    continue
                }
                let fill = shape.fill.map { ";background:#\($0)" } ?? ""
                out += "<div class=\"s\" style=\"\(box)\(fill)\">"
                for paragraph in shape.paragraphs {
                    out += "<p style=\"text-align:\(paragraph.align)\">"
                    if paragraph.runs.isEmpty { out += "&nbsp;" }
                    for run in paragraph.runs {
                        let size = (run.size ?? 18) * 12_700 * scale
                        var style = "font-size:\(px(size))px;color:\(run.color.map { "#" + $0 } ?? textColor)"
                        if run.bold { style += ";font-weight:600" }
                        if run.italic { style += ";font-style:italic" }
                        out += "<span style=\"\(style)\">\(escape(run.text))</span>"
                    }
                    out += "</p>"
                }
                out += "</div>"
            }
            out += "<span class=\"n\">\(index + 1)</span></div>"
        }
        return out + "</body></html>"
    }

    private static func px(_ value: Double) -> String { String(format: "%.1f", value) }

    static func escape(_ text: String) -> String {
        text.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;")
    }

    /// 0 (black) to 1 (white), for picking a readable default text color.
    static func luminance(_ hex: String) -> Double {
        guard hex.count == 6, let value = UInt32(hex, radix: 16) else { return 1 }
        let r = Double(value >> 16 & 0xFF), g = Double(value >> 8 & 0xFF), b = Double(value & 0xFF)
        return (0.299 * r + 0.587 * g + 0.114 * b) / 255
    }
}

/// `presentation.xml`: the slide size (EMU) and the slides' relationship ids in order.
private final class PresentationReader: NSObject, XMLParserDelegate {
    var size = (cx: 0.0, cy: 0.0)
    var order: [String] = []

    static func read(_ data: Data) -> (size: (cx: Double, cy: Double), order: [String]) {
        let reader = PresentationReader()
        let parser = XMLParser(data: data)
        parser.delegate = reader
        parser.parse()
        return (reader.size, reader.order)
    }

    func parser(_ parser: XMLParser, didStartElement name: String, namespaceURI: String?, qualifiedName: String?, attributes: [String: String] = [:]) {
        if name == "p:sldSz" { size = (Double(attributes["cx"] ?? "") ?? 0, Double(attributes["cy"] ?? "") ?? 0) }
        if name == "p:sldId", let id = attributes["r:id"] { order.append(id) }
    }
}

/// A `.rels` file: relationship id to target path.
private final class Relationships: NSObject, XMLParserDelegate {
    var map: [String: String] = [:]

    static func read(_ url: URL) -> [String: String] {
        guard let data = try? Data(contentsOf: url) else { return [:] }
        let reader = Relationships()
        let parser = XMLParser(data: data)
        parser.delegate = reader
        parser.parse()
        return reader.map
    }

    func parser(_ parser: XMLParser, didStartElement name: String, namespaceURI: String?, qualifiedName: String?, attributes: [String: String] = [:]) {
        if name == "Relationship", let id = attributes["Id"], let target = attributes["Target"] { map[id] = target }
    }
}

/// One slide's XML: its background and shapes (text boxes, filled shapes, pictures, table text).
private final class SlideReader: NSObject, XMLParserDelegate {
    var slide = PptxRenderer.Slide()
    private var path: [String] = []
    private var shape: PptxRenderer.Shape?
    private var placed = false
    private var paragraph: PptxRenderer.Paragraph?
    private var run: PptxRenderer.Run?
    private var collecting = false

    static func read(_ data: Data) -> PptxRenderer.Slide {
        let reader = SlideReader()
        let parser = XMLParser(data: data)
        parser.delegate = reader
        parser.parse()
        return reader.slide
    }

    private static let shapeElements: Set<String> = ["p:sp", "p:pic", "p:graphicFrame", "p:cxnSp"]

    func parser(_ parser: XMLParser, didStartElement name: String, namespaceURI: String?, qualifiedName: String?, attributes: [String: String] = [:]) {
        defer { path.append(name) }
        let parent = path.last ?? ""
        if Self.shapeElements.contains(name), shape == nil {
            shape = PptxRenderer.Shape()
            placed = false
            return
        }
        if name == "a:srgbClr", let value = attributes["val"] {
            if path.contains("p:bg"), shape == nil, slide.background == nil { slide.background = value }
            else if run != nil, path.contains("a:rPr") { run?.color = value }
            else if shape != nil, parent == "a:solidFill", path.contains("p:spPr"), !path.contains("a:ln") { shape?.fill = value }
            return
        }
        guard shape != nil else { return }
        switch name {
        case "a:off" where !placed:
            shape?.x = Double(attributes["x"] ?? "") ?? 0
            shape?.y = Double(attributes["y"] ?? "") ?? 0
        case "a:ext" where !placed && (parent == "a:xfrm" || parent == "p:xfrm"):
            shape?.w = Double(attributes["cx"] ?? "") ?? 0
            shape?.h = Double(attributes["cy"] ?? "") ?? 0
            placed = true
        case "a:blip":
            shape?.image = attributes["r:embed"]
        case "a:p":
            paragraph = PptxRenderer.Paragraph()
        case "a:pPr":
            switch attributes["algn"] {
            case "ctr": paragraph?.align = "center"
            case "r": paragraph?.align = "right"
            case "just": paragraph?.align = "justify"
            default: break
            }
        case "a:r", "a:fld":
            run = PptxRenderer.Run(text: "")
        case "a:rPr":
            if let size = attributes["sz"].flatMap(Double.init) { run?.size = size / 100 }
            run?.bold = attributes["b"] == "1"
            run?.italic = attributes["i"] == "1"
        case "a:t":
            collecting = true
        case "a:br":
            paragraph?.runs.append(PptxRenderer.Run(text: "\n", size: run?.size))
        default:
            break
        }
    }

    func parser(_ parser: XMLParser, foundCharacters string: String) {
        if collecting { run?.text += string }
    }

    func parser(_ parser: XMLParser, didEndElement name: String, namespaceURI: String?, qualifiedName: String?) {
        path.removeLast()
        switch name {
        case "a:t":
            collecting = false
        case "a:r", "a:fld":
            if let run, !run.text.isEmpty { paragraph?.runs.append(run) }
            run = nil
        case "a:p":
            if let paragraph { shape?.paragraphs.append(paragraph) }
            paragraph = nil
        case _ where Self.shapeElements.contains(name) && !path.contains(where: Self.shapeElements.contains):
            if let shape, shape.w > 0, shape.h > 0, shape.image != nil || shape.fill != nil || !shape.paragraphs.isEmpty {
                slide.shapes.append(shape)
            }
            shape = nil
        default:
            break
        }
    }
}
